const paper = $json;
const doi = (paper.doi || '').replace('https://doi.org/', '').replace('http://doi.org/', '').trim();
const hasRealDoi = doi && !doi.startsWith('arxiv:') && doi.length > 5;

return {
  json: {
    ...paper,
    doi_clean: doi,
    has_doi: hasRealDoi,
    verify_doi: hasRealDoi ? doi : null
  }
};

const paper = $('Prepare Verification').all().find(p => p.json.doi_clean === $('Has Real DOI?').first().json.doi_clean)?.json || $json;
const doiCheck = $('DOI Resolution Check').first();
const crossrefCheck = $('CrossRef Metadata Check').first().json;

const doiResolves = doiCheck?.json?.$response?.statusCode !== undefined
  ? doiCheck.json.$response.statusCode < 400
  : false;

let crossrefMatch = false;
let crossrefNotes = [];
const crWork = crossrefCheck.message;
if (crWork) {
  const crTitle = Array.isArray(crWork.title) ? crWork.title[0] : crWork.title || '';
  const crTitleNorm = crTitle.toLowerCase().replace(/[^a-z0-9]/g, '');
  const paperTitleNorm = (paper.title || '').toLowerCase().replace(/[^a-z0-9]/g, '');
  const similarity = crTitleNorm.length > 10 && paperTitleNorm.length > 10
    ? (crTitleNorm.substring(0, 30) === paperTitleNorm.substring(0, 30))
    : false;
  crossrefMatch = similarity;
  if (crWork.publisher) crossrefNotes.push('Publisher: ' + crWork.publisher);
  if (crWork['is-referenced-by-count'] !== undefined) crossrefNotes.push('CrossRef citations: ' + crWork['is-referenced-by-count']);
}

const verificationStatus = !paper.has_doi ? 'no_doi'
  : (doiResolves && crossrefMatch) ? 'verified'
  : (doiResolves && !crossrefMatch) ? 'doi_resolves'
  : (!doiResolves && crossrefMatch) ? 'metadata_match'
  : 'unresolved';

return {
  json: {
    ...paper,
    verification: {
      status: verificationStatus,
      doi_resolves: doiResolves,
      crossref_match: crossrefMatch,
      retraction_check: 'not_checked',
      notes: crossrefNotes.join('; '),
      verified_at: new Date().toISOString()
    }
  }
};

const paper = $json;
return {
  json: {
    ...paper,
    verification: {
      status: 'no_doi',
      doi_resolves: false,
      crossref_match: false,
      retraction_check: 'not_applicable',
      notes: 'No DOI available. Verification based on metadata only.',
      verified_at: new Date().toISOString()
    }
  }
};

const papers = $input.first().json.data || [];
const stats = {
  total: papers.length,
  verified: papers.filter(p => p.verification?.status === 'verified').length,
  doi_resolves: papers.filter(p => p.verification?.status === 'doi_resolves').length,
  no_doi: papers.filter(p => p.verification?.status === 'no_doi').length,
  unresolved: papers.filter(p => p.verification?.status === 'unresolved').length
};
console.log('Verification complete:', JSON.stringify(stats));
return {
  json: {
    papers: papers,
    verification_stats: stats,
    verified_at: new Date().toISOString()
  }
};
